327	Cohort & $N$ & Mean $\Delta$ (pp) & SD (pp) & 95\% CI \\
328	\midrule
329	2023 & 1,080 & ${+}2.35$ & 0.88 & $[{+}2.30, {+}2.40]$ \\
330	2024 & 807 & ${+}2.06$ & 1.04 & $[{+}1.99, {+}2.13]$ \\
331	Other & 3,340 & ${+}2.05$ & 0.92 & $[{+}2.02, {+}2.08]$ \\
332	\bottomrule
333	\end{tabular}
334	\end{table}
